-- Chile deep-dive content: page, stats, file_format cards,
-- scope_transmission cards + lifecycle card ("The clearance flow"),
-- steps, penalties_related cards, portal. No penalty rows/table.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Centralised clearance (SII)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. CAF procedures, TED specifications, and penalty calculations continue to evolve — confirm current requirements directly with the SII before building an integration.', 'Chile was one of Latin America''s earliest movers on e-invoicing — the system is mature enough that most of today''s activity is about extending it (boleta, digital delivery) rather than building it.', 'Chile''s DTE model rests on two pillars: the folio authorisation (CAF) that legitimises your invoice numbers, and the electronic stamp (TED) that makes each document verifiable.', 'A DTE only becomes legally valid once SII has validated it — this is a genuine clearance model, not a self-certifying one.', 'Accreditation as an authorised issuer is a genuine certification process with the SII, not a self-serve signup.', 'The sharpest practical risk in Chile isn''t the fine itself — it''s losing the ability to invoice at all.' FROM countries WHERE name_en = 'Chile';

