INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Document types', '[["33 / 34", "Factura Electrónica (affected / exempt)"], ["39 / 41", "Boleta Electrónica (affected / exempt)"], ["61", "Nota de Crédito"], ["Others", "Nota de Débito, Guía de Despacho, export invoices/notes"]]', 'Each DTE type is identified by its own numeric code — get this wrong and the document is processed as the wrong type entirely, not just flagged for review.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'CAF — Código de Autorización de Folios', '[["What it is", "An SII-signed XML file authorising a specific folio range"], ["Requested via", "SII web portal or API, authenticated with a digital certificate"], ["Folio rule", "Sequential — cannot be skipped or reused"]]', 'Unlike systems where invoice numbering is just an internal convention, Chile''s folio numbers are a government-issued resource you draw down from — running out means requesting a new CAF before you can issue anything further.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'TED — Timbre Electrónico Digital', '[["What it is", "An electronic stamp derived from an encrypted data string"], ["Printed form", "PDF417 barcode on the visual representation"], ["Signature", "XMLDSig, using an accredited personal digital certificate"]]', 'Without both the TED and the XMLDSig signature, a DTE has no tax validity — these aren''t optional integrity add-ons, they''re what makes the document legally an invoice at all.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Mandatory identifier', '[["RUT", "Rol Único Tributario — format XX.XXX.XXX-Y"], ["Check digit", "Y, calculated with modulo 11"]]', 'Every DTE must carry a valid RUT for both parties — validate the modulo-11 check digit before submission to catch typos that would otherwise cause rejection.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Monthly reconciliation', '[["Old system", "Books of Purchases and Sales"], ["Replaced by", "Form F29, pre-populated from issued/received DTEs"], ["Data source", "RCV (Registro de Compras y Ventas)"]]', 'Because F29 draws directly from your DTE activity, discrepancies between what you''ve issued/received and what you declare tend to surface automatically — DTE data and VAT filing are tightly coupled in Chile.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'API access for CAF management', '[["Environments", "Separate certification and production modes"], ["Authentication", "Digital certificate belonging to the CAF holder or an authorised representative"]]', 'Third-party gateways exist specifically to let invoicing software providers request, store, and track CAF folios programmatically rather than through manual SII portal logins.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Boleta batch model', '[["Document type", "Boleta Electrónica (39/41)"], ["Submission", "Simplified requirements, batch model for retail/POS scenarios"]]', 'Retail boletas follow a lighter submission process than full facturas — worth knowing if you''re building for high-volume point-of-sale rather than B2B invoicing.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

