INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '💸 UTM-denominated fines', NULL, NULL, 'Late or missing DTE transmission to the SII triggers administrative fines calculated in UTM (Unidad Tributaria Mensual, an inflation-indexed monthly tax unit) plus interest — the peso value shifts with inflation, so don''t anchor to a fixed figure.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🚫 CAF restriction — the real deterrent', NULL, NULL, 'Repeated non-compliance or irregularities can lead the SII to restrict a taxpayer''s ability to download new CAFs — effectively paralysing their ability to issue any invoices at all until the situation is resolved. This is a far more disruptive consequence than most fine schedules in this tracker.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🔗 RCV as an automatic cross-check', NULL, NULL, 'Because your monthly F29 VAT declaration is pre-populated from the Registro de Compras y Ventas, inconsistencies between your DTE activity and your declared figures tend to surface without you needing to be audited first.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Chile';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🧾 Related obligations to track', NULL, NULL, 'VAT on digital services and Guía de Despacho (dispatch guides for goods in transit) both sit within the same DTE family — confirm which additional document types apply to your specific business activity.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Chile' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

